window.GEO_TIPS={"半总统制": "总统与总理分享行政权：总统通常主导外交与国防，总理领导内阁并对议会负责。当总统与议会多数分属不同阵营时，可能出现“左右共治”。法国是典型样本。", "总统制": "总统由选民直接或间接产生，身兼国家元首与政府首脑，行政权独立于立法机构。其优势在于决策链条短、授权明确；治理质量取决于法院、议会与媒体等制衡机制的实际效力。", "议会制": "政府由议会多数党或政党联盟产生，对议会负责，行政与立法深度融合。政府可通过不信任投票更替，政治重组不一定伴随社会动荡。", "君主立宪": "君主作为国家象征保留礼仪性角色，日常治理由民选产生的政府承担。这一安排在历史传统、国家认同与现代民主之间寻求平衡。", "绝对君主制": "君主掌握实际最高权力，内阁与协商机构多由王室设立并向其负责。常见于海湾地区，政治稳定与王室继承秩序、资源分配能力高度相关。", "一党": "单一政党在宪法框架内居于领导地位，政策连续性与长期规划能力突出；权力监督主要依靠党内民主、纪检监察与制度程序设计。", "军政府": "武装力量直接主导政治权力，通常以“恢复秩序”为执政合法性来源，多承诺政治过渡；公民社会与反对派空间往往受到明显压缩。", "神权": "宗教权威构成国家权力的最终来源，宗教律法与世俗行政机构并存。伊朗伊斯兰共和制（最高领袖制）是当代主要形态。", "过渡": "非常态政府形态，多出现于战争、危机或政权更迭之后，以恢复宪政秩序为主要目标，任内选举时间表常随局势调整。", "教派分权": "政治职位按宗教教派比例预先分配（如黎巴嫩：总统属马龙派、总理属逊尼派、议长属什叶派）。旨在维系多元社群平衡，但也容易造成决策僵局与庇护网络。", "联邦": "权力在联邦与地方之间作宪法性划分，地方保有立法、财政与教育等领域自主权，适合疆域广阔或族裔宗教多元的社会。", "战乱": "中央政府权威碎片化，武装派别或地方势力实际控制部分领土，公共服务体系受损严重，人道主义危机风险高。", "社会主义市场": "市场在资源配置中起决定性作用，同时保持公有制主体地位与政府战略规划能力，是中国改革开放后确立的基本经济制度。", "社会市场经济": "市场竞争秩序与社会保障体系的制度性结合，强调“竞争+公平”的平衡，起源于战后德国，影响了整个欧盟经济架构。", "计划经济": "生产、投资与分配主要由国家计划决定，价格信号作用有限。曾在特定历史阶段支撑快速工业化，也面临激励不足与信息效率的长期挑战。", "国家资本主义": "国家通过主权基金、国有企业和战略产业直接参与并引导经济活动，介于自由市场与中央计划之间，能源与金融常为核心抓手。", "资源": "财政与出口高度依赖油气或矿产资源，容易受到“资源诅咒”影响——国际价格波动直接传导至就业与民生，经济多元化是共同课题。", "混合": "公有与私营部门并存，市场机制与政府调控共同配置资源，是全球多数发展中经济体的现实形态，具体比例因国而异。", "援助": "外汇与财政较大程度依赖国际援助或海外侨汇，本土产业基础薄弱，对外部环境变化敏感。", "战争经济": "经济运行围绕战争需求组织，正常市场秩序中断，配给与外援成为关键变量，人道主义通道本身就是经济命脉。", "转型": "从计划经济向市场经济转型的经济体，私有化与制度建设仍在进行中，常伴随寡头化与地区发展不均问题。", "发达资本": "以私有产权和市场配置为基础，政府通过社会保障、监管与产业政策进行调节，服务业占主导，增长依赖创新与全球贸易。"};
